def crossings(ann, cre, cache):
    key = (ann, cre)
    if key in cache:
        return cache[key]
    if not any(a in cre for a in ann):
        result = [(cre, ann, 1 - 2 * ((len(ann) * len(cre)) % 2))]
    else:
        a = ann[-1]
        rest = ann[:-1]
        sign = 1 - 2 * (len(cre) % 2)
        result = []
        for c, b, value in crossings(rest, cre, cache):
            result.append((c, b + (a,), sign * value))
        if a in cre:
            p = cre.index(a)
            sign = 1 - 2 * (p % 2)
            reduced = cre[:p] + cre[p + 1:]
            for c, b, value in crossings(rest, reduced, cache):
                result.append((c, b, sign * value))
    cache[key] = result
    return result


def wedge(left, right, cache):
    key = (left, right)
    if key in cache:
        return cache[key]
    sign = 1
    for a in left:
        for b in right:
            if a == b:
                cache[key] = ((), 0)
                return cache[key]
            if a > b:
                sign = -sign
    result = (tuple(sorted(left + right)), sign)
    cache[key] = result
    return result


